const updateWrap = document.getElementById("appUpdateWrap");
const updateStatus = document.getElementById("appUpdateStatus");
const updateButton = document.getElementById("appUpdateButton");
const forceUpdateBackdrop = document.getElementById("forceUpdateBackdrop");
const forceUpdateStatus = document.getElementById("forceUpdateStatus");
const forceUpdateButton = document.getElementById("forceUpdateButton");
const isNativeApp = Boolean(window.Capacitor?.isNativePlatform?.());
if (isNativeApp) document.body.classList.add("native-app");

async function checkAppUpdate() {
  const appUpdater = window.Capacitor?.Plugins?.AppUpdater;
  if (!window.Capacitor?.isNativePlatform?.() || !appUpdater) return;
  if (updateWrap) updateWrap.hidden = false;
  try {
    const info = await appUpdater.getInfo();
    const response = await fetch(
      "https://raw.githubusercontent.com/icebeg4-hue/davomat1/main/update.json?cache=" +
      Date.now(),
      { cache: "no-store" }
    );
    if (!response.ok) throw new Error("Yangilanish ro‘yxati ochilmadi");
    const update = await response.json();
    const currentCode = Number(info.versionCode || 0);
    if (Number(update.versionCode) > currentCode) {
      if (isNativeApp && forceUpdateBackdrop) {
        forceUpdateBackdrop.hidden = false;
        if (forceUpdateStatus) {
          forceUpdateStatus.textContent =
            "Yangi " + update.version + " versiyasi mavjud. Ilovani ishlatish uchun yangilang.";
        }
        if (forceUpdateButton) {
          forceUpdateButton.onclick = async () => {
            forceUpdateButton.disabled = true;
            forceUpdateStatus.textContent = "Yangilanish yuklanmoqda...";
            try {
              await appUpdater.downloadAndInstall({
                url: update.apkUrl + "?v=" + update.versionCode,
                sha256: update.sha256
              });
              forceUpdateStatus.textContent =
                "Yuklash tugadi. Telefon o‘rnatishni tasdiqlang.";
            } catch (error) {
              forceUpdateStatus.textContent =
                "Yangilanishni yuklab bo‘lmadi. Internetni tekshirib qayta urinib ko‘ring.";
            } finally {
              forceUpdateButton.disabled = false;
            }
          };
        }
      }
      if (updateStatus) {
        updateStatus.textContent =
          "Yangi versiya " + update.version + " mavjud." +
          (update.releaseNotes ? " " + update.releaseNotes : "");
      }
      if (updateButton) {
        updateButton.hidden = false;
        updateButton.onclick = async () => {
          updateButton.disabled = true;
          updateStatus.textContent = "Yangilanish yuklanmoqda...";
          try {
            await appUpdater.downloadAndInstall({
              url: update.apkUrl + "?v=" + update.versionCode,
              sha256: update.sha256
            });
            updateStatus.textContent =
              "Yuklash tugadi. Telefon o‘rnatishni tasdiqlang.";
          } catch (error) {
            updateStatus.textContent =
              "Yangilanishni yuklab bo‘lmadi: " +
              (error?.message || "Noma’lum xato");
          } finally {
            updateButton.disabled = false;
          }
        };
      }
    } else if (updateStatus) {
      updateStatus.textContent =
        "Ilova eng so‘nggi versiyada (" + info.versionName + ").";
    }
  } catch (error) {
    if (updateStatus) {
      updateStatus.textContent =
        "Yangilanish tekshirilmadi: " +
        (error?.message || "Internetga ulanishni tekshiring");
    }
  }
}

function activateSection(tabId, focusTab) {
  const tabs = Array.from(document.querySelectorAll(".section-tab"));
  tabs.forEach(tab => {
    const active = tab.id === tabId;
    tab.classList.toggle("active", active);
    tab.setAttribute("aria-selected", String(active));
    tab.tabIndex = active ? 0 : -1;
    $(tab.getAttribute("aria-controls")).hidden = !active;
  });
  if (focusTab) $(tabId).focus();
  window.scrollTo(0, 0);
}
const sectionTabList = document.querySelector(".section-tabs");
sectionTabList.addEventListener("click", e => {
  const tab = e.target.closest(".section-tab");
  if (tab) activateSection(tab.id, false);
});
sectionTabList.addEventListener("keydown", e => {
  const tabs = Array.from(sectionTabList.querySelectorAll(".section-tab"));
  const current = tabs.indexOf(document.activeElement);
  if (current < 0) return;
  let next = current;
  if (e.key === "ArrowRight") next = (current + 1) % tabs.length;
  else if (e.key === "ArrowLeft") next = (current + tabs.length - 1) % tabs.length;
  else if (e.key === "Home") next = 0;
  else if (e.key === "End") next = tabs.length - 1;
  else return;
  e.preventDefault();
  activateSection(tabs[next].id, true);
});

function refreshWheelDisplay(id) {
  const entry = wheelInputs[id];
  if (!entry) return;
  if (entry.input.tagName === "SELECT") {
    const option = entry.input.options[entry.input.selectedIndex];
    entry.trigger.textContent = option ? option.textContent : "";
    entry.trigger.disabled = entry.input.disabled;
    return;
  }
  const parts = entry.input.value.split(/[-:]/).map(Number);
  entry.trigger.textContent = entry.input.type === "date" ?
    pad(parts[2]) + "." + pad(parts[1]) + "." + parts[0] :
    pad(parts[0]) + ":" + pad(parts[1]);
}
function closeWheelPicker() {
  if (!activeWheelInput) return;
  const input = activeWheelInput;
  $("wheelBackdrop").hidden = true;
  document.body.classList.remove("wheel-modal-open");
  document.removeEventListener("keydown", onWheelKeydown);
  activeWheelInput = null;
  wheelState = null;
  wheelInputs[input.id].trigger.focus();
}
function onWheelKeydown(e) {
  if (e.key === "Escape") closeWheelPicker();
}
function wheelDaysInMonth() { return new Date(wheelState.year, wheelState.month, 0).getDate(); }
function renderWheelColumns() {
  const isDate = activeWheelInput.type === "date";
  const isSelect = activeWheelInput.tagName === "SELECT";
  const columns = $("wheelColumns");
  columns.classList.toggle("time-columns", !isDate && !isSelect);
  columns.classList.toggle("select-columns", isSelect);
  const defs = isDate ? [
    { key: "day", label: "Kun", values: Array.from({ length: wheelDaysInMonth() }, (_, i) => i + 1), format: pad },
    { key: "month", label: "Oy", values: Array.from({ length: 12 }, (_, i) => i + 1), format: v => WHEEL_MONTHS[v - 1] },
    { key: "year", label: "Yil", values: Array.from({ length: Math.max(new Date().getFullYear() + 2, wheelState.year) - Math.min(new Date().getFullYear() - 10, wheelState.year) + 1 }, (_, i) => Math.min(new Date().getFullYear() - 10, wheelState.year) + i), format: String }
  ] : isSelect ? [
    { key: "optionIndex", label: activeWheelInput.id.indexOf("Cls") >= 0 || activeWheelInput.id === "cls" ? "Sinf" : "O‘quvchi", values: Array.from({ length: activeWheelInput.options.length }, (_, i) => i), format: i => activeWheelInput.options[i].textContent }
  ] : [
    { key: "hour", label: "Soat", values: Array.from({ length: 24 }, (_, i) => i), format: pad },
    { key: "minute", label: "Daqiqa", values: Array.from({ length: 60 }, (_, i) => i), format: pad }
  ];
  columns.innerHTML = defs.map(def => {
    const selected = wheelState[def.key];
    return "<div class='wheel-unit'><div class='wheel-label'>" + def.label + "</div><div class='wheel-column' role='listbox' aria-label='" + def.label + "' data-key='" + def.key + "'>" +
      def.values.map((value, i) => {
        const label = String(def.format(value));
        return "<button type='button' class='wheel-item" + (value === selected ? " selected" : "") + "' role='option' aria-selected='" + (value === selected) + "' title='" + esc(label) + "' data-index='" + i + "' data-value='" + value + "'>" + esc(label) + "</button>";
      }).join("") +
      "</div></div>";
  }).join("");
  columns.querySelectorAll(".wheel-column").forEach(column => {
    const key = column.dataset.key, def = defs.find(d => d.key === key);
    column.scrollTop = def.values.indexOf(wheelState[key]) * 44;
    column.addEventListener("scroll", () => {
      clearTimeout(wheelScrollTimer);
      wheelScrollTimer = setTimeout(() => {
        if (!columns.contains(column)) return;
        const index = Math.max(0, Math.min(def.values.length - 1, Math.round(column.scrollTop / 44)));
        updateWheelPart(key, def.values[index]);
      }, 120);
    });
    column.addEventListener("click", e => {
      const item = e.target.closest(".wheel-item");
      if (item) updateWheelPart(key, Number(item.dataset.value));
    });
  });
}
function updateWheelPart(key, value) {
  if (!wheelState || wheelState[key] === value) return;
  wheelState[key] = value;
  if (activeWheelInput.type === "date" && wheelState.day > wheelDaysInMonth()) wheelState.day = wheelDaysInMonth();
  renderWheelColumns();
}
function openWheelPicker(input) {
  activeWheelInput = input;
  if (input.tagName === "SELECT") {
    wheelState = { optionIndex: Math.max(0, input.selectedIndex) };
    $("wheelTitle").textContent = input.id.indexOf("Cls") >= 0 || input.id === "cls" ? "Sinf tanlash" : "O‘quvchini tanlash";
  } else if (input.type === "date") {
    const parts = (input.value || today()).split("-").map(Number);
    wheelState = { year: parts[0], month: parts[1], day: parts[2] };
    $("wheelTitle").textContent = "Sana tanlash";
  } else {
    const parts = (input.value || nowStr()).split(":").map(Number);
    wheelState = { hour: parts[0], minute: parts[1] };
    $("wheelTitle").textContent = "Vaqt tanlash";
  }
  document.body.classList.add("wheel-modal-open");
  $("wheelBackdrop").hidden = false;
  renderWheelColumns();
  document.addEventListener("keydown", onWheelKeydown);
  $("wheelCancel").focus();
}
function applyWheelSelection() {
  if (!activeWheelInput) return;
  if (activeWheelInput.tagName === "SELECT") activeWheelInput.selectedIndex = wheelState.optionIndex;
  else activeWheelInput.value = activeWheelInput.type === "date" ?
    wheelState.year + "-" + pad(wheelState.month) + "-" + pad(wheelState.day) :
    pad(wheelState.hour) + ":" + pad(wheelState.minute);
  activeWheelInput.dispatchEvent(new Event("input", { bubbles: true }));
  activeWheelInput.dispatchEvent(new Event("change", { bubbles: true }));
  closeWheelPicker();
}
function initAndroidWheelPickers() {
  if (!/Android/i.test(navigator.userAgent)) return;
  document.body.classList.add("android-wheel-picker");
  ["fdate", "date", "earlyDate", "earlyListDate", "time", "earlyTime", "cls", "name", "earlyCls", "earlyName"].forEach(id => {
    const input = $(id), isDate = input.type === "date", isSelect = input.tagName === "SELECT";
    let wrapper = input.parentElement;
    const wrapperClass = isSelect ? "select-wrap" : isDate ? "date-wrap" : "time-wrap";
    if (!wrapper.classList.contains(wrapperClass)) {
      wrapper = document.createElement("div");
      wrapper.className = wrapperClass;
      input.parentNode.insertBefore(wrapper, input);
      wrapper.appendChild(input);
    }
    const trigger = document.createElement("button");
    trigger.type = "button";
    trigger.id = id + "WheelTrigger";
    trigger.className = "wheel-picker-trigger";
    trigger.setAttribute("aria-label", isSelect ?
      (id.indexOf("Cls") >= 0 || id === "cls" ? "Sinfni tanlash" : "O‘quvchini tanlash") :
      isDate ? "Sanani tanlash" : "Vaqtni tanlash");
    input.classList.add("wheel-picker-source");
    input.tabIndex = -1;
    input.insertAdjacentElement("afterend", trigger);
    const label = document.querySelector("label[for='" + id + "']");
    if (label) label.htmlFor = trigger.id;
    wheelInputs[id] = { input, trigger };
    refreshWheelDisplay(id);
    input.addEventListener("change", () => refreshWheelDisplay(id));
    trigger.addEventListener("click", () => openWheelPicker(input));
  });
  $("wheelCancel").onclick = closeWheelPicker;
  $("wheelApply").onclick = applyWheelSelection;
  $("wheelBackdrop").onclick = e => { if (e.target === $("wheelBackdrop")) closeWheelPicker(); };
}
function makeXlsx(rows, sheet) {
  if (typeof XLSX === "undefined") throw new Error("xlsx");
  const ws = XLSX.utils.aoa_to_sheet(rows);
  ws["!cols"] = [{ wch: 5 }, { wch: 30 }, { wch: 8 }, { wch: 12 }, { wch: 12 }, { wch: 14 }, { wch: 28 }, { wch: 20 }, { wch: 10 }];
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, sheet);
  return XLSX.write(wb, { type: "array", bookType: "xlsx" });
}

async function downloadXlsx(filename, data) {
  const blob = new Blob([data], {
    type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
  });

  const ios = /iPhone|iPad|iPod/i.test(navigator.userAgent);
  if (ios && typeof navigator.share === "function" && typeof navigator.canShare === "function" && typeof File !== "undefined") {
    const file = new File([blob], filename, { type: blob.type });
    if (navigator.canShare({ files: [file] })) {
      try {
        await navigator.share({
          files: [file],
          title: filename
        });
        return;
      } catch (err) {
        if (err && err.name === "AbortError") throw err;
      }
    }
  }

  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  link.rel = "noopener";
  document.body.appendChild(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 60000);
}

