function compressEarlyPhoto(file) {
  return new Promise((resolve, reject) => {
    const image = new Image(), url = URL.createObjectURL(file);
    image.onload = () => {
      URL.revokeObjectURL(url);
      const scale = Math.min(1, 1400 / Math.max(image.naturalWidth, image.naturalHeight));
      const canvas = document.createElement("canvas");
      canvas.width = Math.round(image.naturalWidth * scale);
      canvas.height = Math.round(image.naturalHeight * scale);
      const context = canvas.getContext("2d");
      if (!context) { reject(new Error("Suratni tayyorlab bo‘lmadi.")); return; }
      context.drawImage(image, 0, 0, canvas.width, canvas.height);
      canvas.toBlob(blob => {
        if (!blob) { reject(new Error("Suratni tayyorlab bo‘lmadi.")); return; }
        if (blob.size > 650000) { reject(new Error("Surat hajmi katta. Yaqinroq masofadan qayta suratga oling.")); return; }
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result);
        reader.onerror = () => reject(new Error("Suratni o‘qib bo‘lmadi."));
        reader.readAsDataURL(blob);
      }, "image/jpeg", 0.82);
    };
    image.onerror = () => { URL.revokeObjectURL(url); reject(new Error("Rasm formatini ochib bo‘lmadi.")); };
    image.src = url;
  });
}

async function renderEarlyList() {
  const day = $("earlyListDate").value;
  const list = earlyRecords.filter(r => r.date === day).sort((a, b) => (a.time < b.time ? -1 : 1));
  $("earlyCount").textContent = "Jami: " + list.length;
  $("earlyEmpty").style.display = list.length ? "none" : "block";
  let rows;
  try { rows = await Promise.all(list.map(async r => ({ record: r, photo: r.photo || (r.photoKey ? await storeEarlyPhoto(r.photoKey, null, "get") : "") }))); }
  catch (err) {
    $("earlyListMsg").textContent = err.message || "Suratlarni o‘qib bo‘lmadi.";
    $("earlyListMsg").className = "msg err";
    return;
  }
  if (day !== $("earlyListDate").value) return;
  $("earlyListMsg").textContent = "";
  $("earlyListMsg").className = "msg";
  $("earlyRows").innerHTML = rows.map((item, i) => {
    const r = item.record, photo = item.photo ? "<a href='" + esc(item.photo) + "' target='_blank' rel='noopener'><img class='early-photo-thumb' src='" + esc(item.photo) + "' alt='Hujjat surati'></a>" : "—";
    return "<tr><td class='n'>" + (i + 1) + "</td><td class='name'>" + esc(r.name) + "</td><td class='c'>" + esc(r.cls) + "</td><td class='t'>" + fmtD(r.date) + " " + esc(r.time) + "</td><td class='why'>" + esc(r.note || "—") + "</td><td>" + photo + "</td><td class='act'><button class='del' data-id='" + esc(r.id) + "'>O‘chirish</button></td></tr>";
  }).join("");
}

